#include "network_data_state.h"
PAPACC_RESULT papacc_network_data_protocol_init(PAPACC_NETWORK_DATA_PROTOCOL *p,PAPACC_U64 sid,PAPACC_U64 cid){if(p==NULL||sid==0U||cid==0U)return PAPACC_RESULT_INVALID_ARGUMENT;if(p->state!=PAPACC_NETWORK_DATA_UNINITIALIZED)return PAPACC_RESULT_INVALID_STATE;p->session_instance_id=sid;p->channel_instance_id=cid;p->state=PAPACC_NETWORK_DATA_WAIT_OPEN;return PAPACC_RESULT_OK;}
PAPACC_RESULT papacc_network_data_protocol_accept(PAPACC_NETWORK_DATA_PROTOCOL *p,PAPACC_U16 type,const PAPACC_U8 *data,PAPACC_SIZE size){PAPACC_RESULT r;if(p==NULL||p->state==PAPACC_NETWORK_DATA_UNINITIALIZED||p->state==PAPACC_NETWORK_DATA_TERMINAL)return PAPACC_RESULT_INVALID_STATE;if(p->state!=PAPACC_NETWORK_DATA_WAIT_OPEN||type!=PAPACC_MESSAGE_TYPE_NETWORK_OPEN)return PAPACC_RESULT_PROTOCOL_ERROR;if(data==NULL||size>PAPACC_NETWORK_OPEN_MAX_PAYLOAD)return PAPACC_RESULT_LIMIT_EXCEEDED;r=papacc_network_open_decode(data,size,&p->request);if(r!=PAPACC_RESULT_OK)return r;p->state=PAPACC_NETWORK_DATA_ESTABLISHING;return PAPACC_RESULT_OK;}
void papacc_network_data_protocol_shutdown(PAPACC_NETWORK_DATA_PROTOCOL *p){if(p!=NULL)*p=(PAPACC_NETWORK_DATA_PROTOCOL)PAPACC_NETWORK_DATA_PROTOCOL_INITIALIZER;}
